(1, 12, '字节跳动', NULL, '互联网',       '10000人以上', '北京市海淀区北三环西路43号字节跳动大厦',   '北京', '字节跳动是全球领先的科技公司，旗下拥有今日头条、抖音、TikTok、飞书等多款知名产品，致力于用技术连接人与信息。公司文化强调"始终创业"，鼓励创新，提供极具竞争力的薪酬和发展空间。', 'https://www.bytedance.com',  '李经理', '010-88880001', 'campus@bytedance.com',  NULL, 1, '资料齐全，审核通过', '2025-10-05 09:00:00', '2025-10-02 09:00:00', '2025-10-05 09:00:00'),
(2, 13, '华为技术有限公司', NULL, '通信/科技',   '10000人以上', '广东省深圳市龙岗区坂田华为基地',           '深圳', '华为是全球领先的ICT基础设施和智能终端提供商，业务遍及170多个国家和地区。公司持续投入研发，拥有强大的技术实力和丰富的人才培养体系，为应届生提供完善的成长通道。',                   'https://www.huawei.com',     '王经理', '0755-28780001', 'campus@huawei.com',   NULL, 1, '资料齐全，审核通过', '2025-10-05 10:00:00', '2025-10-02 10:00:00', '2025-10-05 10:00:00'),
(3, 14, '阿里巴巴集团', NULL, '互联网/电商', '10000人以上', '浙江省杭州市余杭区文一西路969号阿里巴巴西溪园区', '杭州', '阿里巴巴是中国最大的电子商务和云计算公司，旗下有淘宝、天猫、阿里云、蚂蚁集团等。公司使命是"让天下没有难做的生意"，为年轻人提供广阔的发展平台和创业氛围。',                  'https://www.alibaba.com',    '张经理', '0571-85220001', 'campus@alibaba.com',  NULL, 1, '资料齐全，审核通过', '2025-10-06 09:00:00', '2025-10-03 09:30:00', '2025-10-06 09:00:00'),
(4, 15, '中原银行',     NULL, '金融',         '5000-10000人', '河南省郑州市郑东新区商鼎路与九如路交叉口',  '郑州', '中原银行是河南省规模最大的城市商业银行，致力于服务地方经济发展。银行拥有完善的培训体系和职业发展通道，为应届毕业生提供管培生、科技岗等多种发展路径。',                         'https://www.zybank.com.cn',  '赵经理', '0371-65520001', 'campus@zybank.com.cn',NULL, 1, '资料齐全，审核通过', '2025-10-06 14:00:00', '2025-10-04 08:45:00', '2025-10-06 14:00:00'),
(5, 16, '宇通客车股份有限公司', NULL, '制造业',     '5000-10000人', '河南省郑州市管城区宇通路宇通工业园',       '郑州', '宇通客车是全球最大的客车制造商，产品远销全球40多个国家和地区。公司注重技术创新，在新能源客车领域处于行业领先地位，为工科毕业生提供丰富的技术岗位和管理岗位。',               'https://www.yutong.com',     '孙经理', '0371-66780001', 'campus@yutong.com',   NULL, 1, '资料齐全，审核通过', '2025-10-07 09:00:00', '2025-10-04 11:00:00', '2025-10-07 09:00:00');

