INSERT INTO `job` (`id`,`company_id`,`title`,`description`,`requirements`,`job_type`,`salary_min`,`salary_max`,`city`,`address`,`education_req`,`major_req`,`headcount`,`category`,`status`,`audit_remark`,`deadline`,`created_at`,`updated_at`) VALUES
-- 字节跳动 (company_id=1) 8 个职位
(1,  1, 'Java后端开发工程师',     '负责字节跳动核心业务系统的后端开发与优化，参与高并发、高可用系统设计。',                     '1. 本科及以上学历，计算机相关专业；\n2. 熟练掌握Java，熟悉Spring Boot框架；\n3. 熟悉MySQL、Redis等常用中间件；\n4. 有良好的编码习惯和团队协作能力。',                        '全职', 18000, 35000, '北京', '海淀区字节跳动大厦',         '本科', '计算机相关专业',     10, '技术', 2, NULL, '2026-06-30', '2025-11-01 09:00:00', '2025-11-05 10:00:00'),
(2,  1, '前端开发工程师',         '负责抖音Web端及中后台系统的前端开发，提升用户体验和页面性能。',                               '1. 本科及以上学历；\n2. 精通HTML/CSS/JavaScript；\n3. 熟悉React或Vue框架；\n4. 有TypeScript开发经验优先。',                                                                '全职', 17000, 32000, '北京', '海淀区字节跳动大厦',         '本科', '计算机/软件工程',   8,  '技术', 2, NULL, '2026-06-30', '2025-11-01 10:00:00', '2025-11-05 10:30:00'),
(3,  1, '数据分析实习生',         '协助数据团队进行用户行为分析、产品数据监控及报表开发。',                                     '1. 在校大三或大四学生；\n2. 熟悉SQL和Python；\n3. 了解常用数据分析方法；\n4. 每周实习不少于4天。',                                                                         '实习', 6000,  8000,  '北京', '海淀区字节跳动大厦',         '本科', '统计/数据科学',     5,  '技术', 2, NULL, '2026-04-30', '2025-11-02 09:00:00', '2025-11-06 09:00:00'),
(4,  1, '产品经理（校招）',       '负责今日头条推荐产品的需求分析、功能设计和项目推进。',                                       '1. 本科及以上学历；\n2. 优秀的逻辑分析和沟通表达能力；\n3. 对互联网产品有浓厚兴趣；\n4. 有产品相关实习经历优先。',                                                          '全职', 16000, 28000, '北京', '海淀区字节跳动大厦',         '本科', '不限',             4,  '产品', 2, NULL, '2026-06-30', '2025-11-03 14:00:00', '2025-11-07 11:00:00'),
(5,  1, '运营专员',               '负责抖音电商的内容运营和达人运营，制定运营策略并推动落地执行。',                               '1. 本科及以上学历；\n2. 优秀的文案撰写和数据分析能力；\n3. 对短视频和电商行业有深入了解。',                                                                                 '全职', 12000, 22000, '上海', '徐汇区字节跳动上海中心',     '本科', '市场营销/传播学',   6,  '运营', 2, NULL, '2026-05-31', '2025-11-05 09:00:00', '2025-11-08 16:00:00'),
(6,  1, 'AI算法工程师',           '参与大语言模型的训练与优化，推动AI技术在产品中的落地应用。',                                   '1. 硕士及以上学历，计算机/人工智能相关专业；\n2. 扎实的机器学习和深度学习基础；\n3. 熟悉PyTorch/TensorFlow；\n4. 有顶会论文发表优先。',                                     '全职', 30000, 55000, '北京', '海淀区字节跳动大厦',         '硕士', '人工智能/计算机',   3,  '技术', 1, NULL, '2026-06-30', '2025-12-10 09:00:00', '2025-12-10 09:00:00'),
(7,  1, '测试开发工程师',         '负责产品的自动化测试框架搭建和质量保障工作。',                                               '1. 本科及以上学历；\n2. 熟悉Python或Java；\n3. 了解自动化测试工具和CI/CD流程。',                                                                                         '全职', 15000, 28000, '北京', '海淀区字节跳动大厦',         '本科', '计算机/软件工程',   5,  '技术', 2, NULL, '2026-05-31', '2025-11-15 10:00:00', '2025-11-20 14:00:00'),
(8,  1, '市场营销实习生',         '协助市场团队进行品牌推广活动的策划与执行，负责线上线下渠道运营。',                             '1. 在校大三或大四学生；\n2. 市场营销或传播学相关专业优先；\n3. 有新媒体运营经验优先。',                                                                                   '实习', 4000,  6000,  '上海', '徐汇区字节跳动上海中心',     '本科', '市场营销/传播学',   3,  '市场', 3, NULL, '2026-03-31', '2025-10-20 09:00:00', '2026-01-05 11:00:00'),

