(2, 2, '华为"勇敢星"校园招聘专场',             '华为2026年应届生招聘专场，涵盖研发、销售、财经等多个方向，现场发放面试Fast Pass。',                                                  '河南大学明伦校区-大礼堂',               '2026-03-15 09:00:00', '2026-03-15 12:00:00', 500, 0,   1, '审核通过', '2025-12-05 10:00:00', '2026-01-18 14:00:00'),
(3, 3, '阿里巴巴春季实习生招聘会',             '阿里巴巴2026春季实习生专场招聘，面向大三、研二在校生，提供技术、产品、运营等多个方向的实习机会。',                                    '郑州西亚斯学院-学术报告厅',             '2026-03-20 14:00:00', '2026-03-20 17:00:00', 200, 89,  1, '审核通过', '2025-12-10 09:00:00', '2026-01-20 11:00:00'),
(4, 4, '中原银行2026校招金融人才见面会',       '中原银行年度校园招聘见面会，介绍银行岗位体系、发展通道和培训机制，现场答疑。',                                                        '河南财经政法大学-学术报告厅',           '2026-03-25 14:00:00', '2026-03-25 16:30:00', 150, 0,   0, NULL,       '2026-01-15 09:00:00', '2026-01-15 09:00:00'),
(5, 5, '宇通客车制造业人才专场招聘会',         '宇通客车2026年校园招聘专场，招聘机械、电气、质量等方向工程师，现场参观宇通工业园。',                                                    '中原工学院-就业指导中心报告厅',         '2025-12-20 09:00:00', '2025-12-20 12:00:00', 100, 45,  3, NULL,       '2025-11-15 10:00:00', '2025-12-20 15:00:00'),
(6, 1, '字节跳动AI技术开放日',                  '字节跳动AI Lab技术分享会，邀请资深算法工程师分享大模型、AIGC等前沿技术，同时开放AI方向校招直通面试。',                                 '郑州大学新校区-信息工程学院报告厅',     '2026-04-05 14:00:00', '2026-04-05 17:00:00', 200, 0,   0, NULL,       '2026-01-20 10:00:00', '2026-01-20 10:00:00');

