-- 11. announcement  公告（12 条）
-- ============================================================
INSERT INTO `announcement` (`id`,`title`,`content`,`type`,`publisher_id`,`status`,`top_flag`,`created_at`,`updated_at`) VALUES
(1,  '校园招聘系统正式上线通知',
     '各位同学、企业用户：\n\n校园招聘系统已于2025年10月1日正式上线运行。本系统旨在搭建高校学生与优质企业之间的桥梁，提供职位发布、简历投递、面试安排、招聘会预约等一站式服务。\n\n请各位用户注册账号后完善个人信息，以便获得更好的服务体验。如有问题，请联系系统管理员。',
     'system', 1, 1, 1, '2025-10-01 08:00:00', '2025-10-01 08:00:00'),
(2,  '2026届春季校园招聘正式启动',
     '2026届春季校园招聘活动已正式启动！\n\n本次春招将有字节跳动、华为、阿里巴巴、中原银行、宇通客车等多家知名企业参与，提供技术、产品、运营、财务等多个方向的岗位。\n\n请同学们及时完善简历，关注心仪企业的职位信息，积极投递申请。',
     'recruitment', 1, 1, 1, '2025-11-01 09:00:00', '2025-11-01 09:00:00'),
(3,  '简历撰写指南——如何打造一份吸引HR的简历',
     '一份优秀的简历是求职成功的第一步。以下是简历撰写的几点建议：\n\n1. 突出与目标岗位相关的经历和技能\n2. 用数据量化工作成果（如"提升了30%的性能"）\n3. 保持简洁，控制在1-2页\n4. 认真检查拼写和语法错误\n5. 根据不同岗位定制简历内容\n\n系统已支持在线简历编辑功能，欢迎使用！',
     'activity', 1, 1, 0, '2025-11-10 10:00:00', '2025-11-10 10:00:00'),
(4,  '字节跳动2026春招宣讲会预告',
     '字节跳动将于2026年3月10日在郑州大学举办2026春季校园招聘宣讲会。\n\n时间：2026年3月10日 14:00-17:00\n地点：郑州大学新校区图书馆报告厅\n\n宣讲内容包括公司介绍、岗位说明、现场Q&A和简历投递。名额有限，请提前在系统中预约！',
     'recruitment', 1, 1, 1, '2025-12-01 09:00:00', '2025-12-01 09:00:00'),
(5,  '华为"勇敢星"校招专场即将开启',
     '华为2026年"勇敢星"校园招聘专场将于3月15日在河南大学举办。\n\n时间：2026年3月15日 09:00-12:00\n地点：河南大学明伦校区大礼堂\n\n本次专场涵盖研发、销售、财经等方向，现场发放面试Fast Pass。欢迎同学们踊跃参与！',
     'recruitment', 1, 1, 0, '2025-12-05 10:00:00', '2025-12-05 10:00:00'),
(6,  '面试技巧分享——助你从容应对校招面试',
     '校招面试季来临，以下几点面试技巧供同学们参考：\n\n1. 充分了解目标公司和岗位\n2. 准备常见面试问题的回答（自我介绍、项目经历、职业规划等）\n3. 技术面试注重基础知识和编码能力\n4. 保持自信、真诚的态度\n5. 面试结束后及时发送感谢信\n\n祝大家面试顺利！',
     'activity', 1, 1, 0, '2025-12-10 14:00:00', '2025-12-10 14:00:00'),
(7,  '系统维护通知（2026年1月18日）',
     '为了提升系统性能和用户体验，系统将于2026年1月18日（周日）凌晨2:00-6:00进行例行维护升级。维护期间系统将暂时无法访问，请各位用户提前做好安排。\n\n给您带来不便，敬请谅解。',
     'system', 1, 1, 0, '2026-01-15 16:00:00', '2026-01-15 16:00:00'),
(8,  '宇通客车制造业人才专场圆满结束',
     '12月20日，宇通客车制造业人才专场招聘会在中原工学院成功举办。\n\n本次招聘会共吸引45名同学参与，现场收到简历30余份，初步达成意向10余人。感谢宇通客车对校园招聘工作的大力支持！',
     'recruitment', 1, 1, 0, '2025-12-21 09:00:00', '2025-12-21 09:00:00'),
(9,  '关于完善个人信息的温馨提示',
     '亲爱的同学们：\n\n系统检测到部分注册用户尚未完善个人档案信息。完整的个人信息有助于企业HR更好地了解您，提高简历通过率。\n\n请前往"个人中心"完善以下信息：\n- 学校、专业、学历信息\n- 技能标签\n- 求职意向和期望薪资\n- 自我介绍\n\n感谢您的配合！',
     'system', 1, 1, 0, '2025-11-20 10:00:00', '2025-11-20 10:00:00'),
(10, '阿里巴巴春季实习生招聘火热进行中',
     '阿里巴巴2026春季实习生招聘已启动，面向大三和研二在校生。\n\n实习方向包括：Java开发、前端开发、数据开发、产品运营、视觉设计等。\n\n宣讲会将于3月20日在郑州西亚斯学院举行，欢迎同学们报名参加！实习表现优秀者可直接转正。',
     'recruitment', 1, 1, 0, '2025-12-15 09:00:00', '2025-12-15 09:00:00'),
(11, '2025年度校招数据统计报告',
     '截至2025年12月31日，校园招聘系统累计数据如下：\n\n- 注册学生：10人\n- 入驻企业：5家\n- 发布职位：32个\n- 简历投递：45次\n- 面试安排：12场\n- 发放Offer：6份\n- 举办招聘会：6场\n\n感谢所有用户的信任与支持，我们将继续优化系统功能，为大家提供更好的服务。',
     'system', 1, 2, 0, '2026-01-02 10:00:00', '2026-01-05 09:00:00'),
(12, '寒假期间系统使用说明',
     '各位用户：\n\n寒假期间（2026年1月20日-2月20日），系统正常运行。企业可继续发布职位和安排面试，学生可正常投递简历和查看通知。\n\n寒假期间客服响应时间可能略有延迟，紧急问题请发送邮件至admin@campus.com。\n\n祝大家假期愉快！',
     'system', 1, 0, 0, '2026-01-18 09:00:00', '2026-01-18 09:00:00');

